contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 amount_, uint256 rate_, uint256 duration_) public payable {
        uint256 actual = c.interestFor(amount_, rate_, duration_); if (__ESBMC_reverted()) return;
        uint256 expectedInterest = (rate_ * duration_) / 365 days;
        uint256 expected = (amount_ * expectedInterest) / 1e18;
        assert(actual == expected);
    }

    receive() external payable {}
}

